pub fn v73_0_verify_operator_key_ct(provided: &str, expected: &str) -> bool {
    let a = provided.as_bytes();
    let b = expected.as_bytes();
    if b.is_empty() {
        return false;
    }
    let mut diff: u8 = if a.len() == b.len() { 0 } else { 1 };
    let max_len = a.len().max(b.len());
    let mut i = 0usize;
    while i < max_len {
        let x = match a.get(i) {
            Some(v) => *v,
            None => 0u8,
        };
        let y = match b.get(i) {
            Some(v) => *v,
            None => 0u8,
        };
        diff |= x ^ y;
        i += 1;
    }
    diff == 0
