    let x = fold61(x_in);
    if n == 0 { return 1; }
    let mut u = 1u64;
    let mut v = x;
    let mut bit: i32 = 59;
    while bit >= 0 {
        let uv = mul_mod61(u, v);
        let mid = sub_mod61(add_mod61(uv, uv), x);
        if ((n >> (bit as u32)) & 1) == 0 {
            let uu = mul_mod61(u, u);
