fn chebyshev_t_m61(n: u64, x: u64) -> u64 {
    let x_mod = m61_reduce(x as u128);
    if n == 0 { return 1; }
    if n == 1 { return x_mod; }
    let two_x = m61_add(x_mod, x_mod);
    let mut v0: u64 = 2;
    let mut v1: u64 = two_x;
    let top_bit = 63 - n.leading_zeros();
    for bit in (0..=top_bit).rev() {
        if ((n >> bit) & 1) == 0 {
            let v0_v1 = m61_mul(v0, v1);
            v1 = m61_sub(v0_v1, two_x);
            v0 = m61_sub(m61_mul(v0, v0), 2);
        } else {
            let v0_v1 = m61_mul(v0, v1);
            v0 = m61_sub(v0_v1, two_x);
            v1 = m61_sub(m61_mul(v1, v1), 2);
        }
    }
    if (v0 & 1) == 0 { v0 >> 1 } else { (v0 + M61_PRIME) >> 1 }
}
