fn i32_to_f16_exact(v: i32) -> u16 {
    if v == 0 { return 0; }
    let sign: u16 = if v < 0 { 0x8000 } else { 0 };
    let mag: u32 = if v < 0 { (-v) as u32 } else { v as u32 };
    let msb: u32 = 31 - mag.leading_zeros();
    let exp: u16 = ((msb + 15) as u16) << 10;
    let rem: u32 = mag ^ (1u32 << msb);
    let mant: u16 = if msb <= 10 {
        ((rem << (10 - msb)) & 0x03FF) as u16
    } else {
        ((rem >> (msb - 10)) & 0x03FF) as u16
    };
    sign | exp | mant
}
```

