fn cpu_ref_k10_udot(va: u32, vb: u32, p0: u32, p1: u32) -> u32 {
    let u_packs = k10_u8_basis_packs();
    let mut acur = va ^ p0;
    let mut bcur = vb ^ p1;
    let mut acc: u32 = 0;
    for _ in 0..8 {
        // Zero-point-shifted [128..191] unsigned activations (MSB=1 strictly proves u8 x u8 -> u32!)
        let ua = (acur & 0x3F3F_3F3F) ^ 0x8080_8080;
        let a0 = ua & 0xFF;
        let a1 = (ua >> 8) & 0xFF;
        let a2 = (ua >> 16) & 0xFF;
        let a3 = (ua >> 24) & 0xFF;
        for up in u_packs {
            let uw = (bcur ^ up) & 0x1F1F_1F1F;
            let w0 = uw & 0xFF;
            let w1 = (uw >> 8) & 0xFF;
            let w2 = (uw >> 16) & 0xFF;
            let w3 = (uw >> 24) & 0xFF;
            acc = acc.wrapping_add(a0 * w0 + a1 * w1 + a2 * w2 + a3 * w3);
        }
        acur = acur.wrapping_add(0x9E37_79B9).rotate_left(7);
        bcur = bcur.wrapping_add(0x85EB_CA6B).rotate_left(11);
    }
    acc.wrapping_sub(0x0008_0000)
}
