fn f32_to_f16_bits(val: f32) -> u16 {
    let bits: u32 = val.to_bits();
    let sign: u16 = ((bits >> 16) & 0x8000) as u16;
    let raw_exp: i32 = ((bits >> 23) & 0xFF) as i32;
    if raw_exp == 0 {
        return sign;
    }
    let exp32: i32 = raw_exp - 127;
    if exp32 > 15 {
        return sign | 0x7C00;
    }
    if exp32 < -14 {
        return sign;
    }
    let exp16: u16 = ((exp32 + 15) as u16) & 0x1F;
    let mant16: u16 = ((bits & 0x007F_FFFF) >> 13) as u16;
    sign | (exp16 << 10) | mant16
}
