fn f16_to_f32_exact(h: u16) -> f32 {
    let sign = ((h >> 15) & 1) as u32;
    let exp = ((h >> 10) & 0x1F) as u32;
    let mant = (h & 0x03FF) as u32;
    let bits: u32 = if exp == 0 {
        if mant == 0 {
            sign << 31
        } else {
            let mut m = mant;
            let mut e: i32 = -14;
            while (m & 0x0400) == 0 {
                m <<= 1;
                e -= 1;
            }
            m &= 0x03FF;
            let f_exp = ((e + 127) as u32) & 0xFF;
            (sign << 31) | (f_exp << 23) | (m << 13)
        }
    } else if exp == 31 {
        (sign << 31) | (0xFF << 23) | (mant << 13)
    } else {
        let f_exp = exp + (127 - 15);
        (sign << 31) | (f_exp << 23) | (mant << 13)
    };
    f32::from_bits(bits)
}
