            let tag = format!("{}({})", t.shape, t.types);
            if !uniq.contains(&tag) && uniq.len() < 12 {
                uniq.push(tag);
            }
        }
    }
    if uniq.is_empty() {
        "0 Subgroup tiles".to_string()
    } else {
        uniq.join(" | ")
    }
