fn posix_ignore_hangup_and_pipe() {
    #[cfg(all(any(target_os = "android", target_os = "linux"), not(target_env = "musl")))]
    unsafe {
        let h = dlopen(b"libc.so\0".as_ptr(), 2);
        if !h.is_null() {
            let p_sig = dlsym(h, b"signal\0".as_ptr());
            if !p_sig.is_null() {
                type FnSignal = unsafe extern "C" fn(i32, usize) -> usize;
                let f_sig: FnSignal = core::mem::transmute(p_sig);
                let _ = f_sig(1, 1);  // SIGHUP -> SIG_IGN
                let _ = f_sig(13, 1); // SIGPIPE -> SIG_IGN
            }
        }
    }
}
